7: $ErrorActionPreference = 'Stop'
8: Import-Module powershell-yaml -ErrorAction Stop
9: $record = Get-Content -LiteralPath $Path -Raw | ConvertFrom-Json
10: $data = ConvertFrom-Yaml -Yaml $record.output -Ordered
11: if (!$Memories) { $data | ConvertTo-Json -Depth 100; return }
12: $found = [System.Collections.Generic.List[object]]::new()
13: function Read-MemoryNode {
14:     param([object]$Node)
15:     if ($Node -is [System.Collections.IDictionary]) {
16:         if ($Node.Contains('id') -and [string]$Node['id'] -like 'MEMORY-*') {
17:             if ($Node['id'] -ne 'MEMORY-PROCESS-007') { $found.Add($Node) }
18:             return
19:         }
20:         foreach ($key in $Node.Keys) { Read-MemoryNode -Node $Node[$key] }
21:     } elseif ($Node -is [System.Collections.IEnumerable] -and $Node -isnot [string]) {
22:         foreach ($child in $Node) { Read-MemoryNode -Node $child }
23:     }
24: }
25: Read-MemoryNode -Node $data
26: Write-Output ('MEMORY_COUNT: ' + $found.Count)
27: $ordered = @($found | Sort-Object { $_['id'] })
28: $selected = if ($Count -gt 0) { @($ordered | Select-Object -Skip ($Start-1) -First $Count) } else { @($ordered | Select-Object -Skip ($Start-1)) }
29: if ($found.Count -eq 0) { Write-Output ('ROOT_KEYS: ' + ($data.Keys -join ',')); Write-Output ('PAYLOAD_KEYS: ' + ($data.payload.Keys -join ',')); Write-Output ('RESULT_KEYS: ' + ($data.payload.result.Keys -join ',')) }
30: foreach ($memory in $selected) { $memory | ConvertTo-Json -Depth 100 }
