115:         SessionLifeUnitGateReports.NormalizeRunId(testRunId)
116:             ?? throw new InvalidOperationException("TestGroups requires --test-run-id, so that every selected project writes its TRX receipt.");
117: 
118:     /// <summary>
119:     /// TR-MCP-NUKE-020 AC-5: every named class ran at least one case. A class counts only through an executed result (an
120:     /// outcome other than NotExecuted) whose test, joined to its definition by test id, belongs to the class: the
121:     /// definition's TestMethod class name is the class, as the whole name or its last segment ('.' or '+' separated). A
122:     /// definition with no executed result, a display name and a namespace segment never count; a custom display name
123:     /// counts through its test's class.
124:     /// </summary>
125:     /// <param name="project">The project whose TRX is checked.</param>
126:     /// <param name="classes">The classes the project's groups named.</param>
127:     /// <param name="xml">The complete TRX content.</param>
128:     /// <returns>Null when every class ran a case; otherwise the failure, naming each class that ran none.</returns>
129:     /// <remarks>
130:     /// <list type="table">
131:     /// <listheader><term>Date</term><description>Requirements; AC; change and reason</description></listheader>
132:     /// <item><term>2026-11-02</term><description>FR-MCP-BUILD-001; TR-MCP-NUKE-020 AC-5: added so a misspelled class in a multi-class group fails instead of passing silently.</description></item>
133:     /// <item><term>2026-11-02</term><description>FR-MCP-BUILD-001; TR-MCP-NUKE-020 AC-5 (appended: a class counts only through an executed result joined to its definition by test id): joins each executed result to its definition and compares the definition's class name, instead of matching text in display names and every definition, because hostile validation finding R9-F1 showed a definition without a result, a display name or a namespace segment satisfied the check (operator 2026-11-02: "Strengthen 5 ACs, fix all 8 (Recommended)").</description></item>
134:     /// </list>
135:     /// </remarks>
136:     internal static string? CheckClasses(string project, IReadOnlyList<string> classes, string xml)
137:     {
138:         ArgumentNullException.ThrowIfNull(classes);
139:         string[] executedClasses;
140:         try
141:         {
142:             var document = XDocument.Parse(xml);
143:             var classById = document.Descendants()
144:                 .Where(element => element.Name.LocalName == "UnitTest")
145:                 .Select(test => (Id: (string?)test.Attribute("id"), ClassName: (string?)test.Elements().FirstOrDefault(child => child.Name.LocalName == "TestMethod")?.Attribute("className")))
146:                 .Where(test => !string.IsNullOrEmpty(test.Id) && !string.IsNullOrEmpty(test.ClassName))
147:                 .GroupBy(test => test.Id!, StringComparer.Ordinal)
148:                 .ToDictionary(group => group.Key, group => group.First().ClassName!, StringComparer.Ordinal);
149:             executedClasses = document.Descendants()
150:                 .Where(element => element.Name.LocalName == "UnitTestResult")
151:                 .Where(result => !string.Equals((string?)result.Attribute("outcome"), "NotExecuted", StringComparison.Ordinal))
152:                 .Select(result => (string?)result.Attribute("testId"))
153:                 .Where(id => id is not null && classById.ContainsKey(id))
154:                 .Select(id => classById[id!])
155:                 .ToArray();
156:         }
157:         catch (System.Xml.XmlException error)
158:         {
159:             return $"Test group project '{project}' wrote unreadable TRX evidence, so classes {string.Join(", ", classes)} are unproven: {error.Message}";
160:         }
161: 
162:         var missing = classes.Where(name => !executedClasses.Any(className => IsClass(className, name))).ToArray();
163:         return missing.Length == 0
164:             ? null
165:             : $"Test group project '{project}' ran no case of class {string.Join(", ", missing)}.";
166:     }
