168:     /// <summary>
169:     /// TR-MCP-NUKE-020 AC-5: whether a definition's class name is the named class, as the whole name or its last segment
170:     /// ('.' or '+' separated, '+' marking a nested class).
171:     /// </summary>
172:     /// <param name="className">The definition's TestMethod class name.</param>
173:     /// <param name="name">The class a group names.</param>
174:     /// <returns>True when the definition belongs to the named class.</returns>
175:     /// <remarks>2026-11-02, FR-MCP-BUILD-001; TR-MCP-NUKE-020 AC-5: added for hostile validation finding R9-F1.</remarks>
176:     private static bool IsClass(string className, string name) =>
177:         string.Equals(className, name, StringComparison.Ordinal)
178:         || className.EndsWith("." + name, StringComparison.Ordinal)
179:         || className.EndsWith("+" + name, StringComparison.Ordinal);
180: }
