32:     /// <summary>Refuses absent, malformed, empty, inconsistent or non-passing TRX counters even when the runner exits zero.</summary>
33:     /// <param name="project">The solution project whose evidence is checked.</param>
34:     /// <param name="xml">The complete TRX content.</param>
35:     /// <returns>Null only for a nonempty zero-failure, zero-skip result.</returns>
36:     internal static string? CheckTrx(string project, string xml)
37:     {
38:         try
39:         {
40:             var document = XDocument.Parse(xml);
41:             var counters = document.Root?.Name.LocalName == "TestRun"
42:                 ? document.Descendants().SingleOrDefault(element => element.Name.LocalName == "Counters") : null;
43:             if (counters is not null && Counter(counters, "total", out var total) && Counter(counters, "passed", out var passed)
44:                 && Counter(counters, "failed", out var failed) && Counter(counters, "notExecuted", out var skipped)
45:                 && total > 0 && total == passed && failed == 0 && skipped == 0)
46:                 return null;
47:         }
48:         catch (Exception error) when (error is System.Xml.XmlException or InvalidOperationException)
49:         {
50:             return $"Integration lane project '{project}' wrote invalid TRX evidence: {error.Message}";
51:         }
52:         return $"Integration lane project '{project}' did not execute a nonempty all-passing scope (zero failures and zero skips required).";
